import { test, expect } from '@playwright/test';

test.describe('Modal Full-Screen on Small Viewports', () => {
  test.beforeEach(async ({ page }) => {
    // Set mobile viewport size
    await page.setViewportSize({ width: 375, height: 667 });
    await page.goto('about:blank');

    // Create a simple HTML page with a modal for testing
    await page.setContent(`
      <!DOCTYPE html>
      <html>
      <head>
        <style>
          body {
            margin: 0;
            padding: 20px;
            font-family: Arial, sans-serif;
          }

          .modal {
            display: none;
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background-color: rgba(0, 0, 0, 0.5);
            z-index: 1000;
          }

          .modal.open {
            display: flex;
            align-items: center;
            justify-content: center;
          }

          .modal-content {
            background-color: white;
            padding: 20px;
            border-radius: 8px;
            max-width: 90%;
            width: 100%;
          }

          @media (max-width: 768px) {
            .modal-content {
              width: 100%;
              height: 100%;
              max-width: 100%;
              border-radius: 0;
              display: flex;
              flex-direction: column;
            }
          }

          .modal-header {
            font-size: 20px;
            font-weight: bold;
            margin-bottom: 10px;
          }

          .modal-body {
            margin-bottom: 20px;
            flex-grow: 1;
            overflow-y: auto;
          }

          .modal-footer {
            display: flex;
            gap: 10px;
            justify-content: flex-end;
          }

          button {
            padding: 10px 20px;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            font-size: 14px;
          }

          .btn-primary {
            background-color: #007bff;
            color: white;
          }

          .btn-secondary {
            background-color: #6c757d;
            color: white;
          }

          .btn-open {
            background-color: #28a745;
            color: white;
          }
        </style>
      </head>
      <body>
        <h1>Modal Test Page</h1>
        <button class="btn-open" id="openModalBtn">Open Modal</button>

        <div id="modal" class="modal">
          <div class="modal-content">
            <div class="modal-header">Modal Title</div>
            <div class="modal-body">
              <p>This is a modal dialog that should be full-screen on mobile devices.</p>
              <p>Lorem ipsum dolor sit amet, consectetur adipiscing elit.</p>
            </div>
            <div class="modal-footer">
              <button class="btn-secondary" id="closeModalBtn">Close</button>
              <button class="btn-primary" id="confirmBtn">Confirm</button>
            </div>
          </div>
        </div>

        <script>
          const modal = document.getElementById('modal');
          const openBtn = document.getElementById('openModalBtn');
          const closeBtn = document.getElementById('closeModalBtn');
          const confirmBtn = document.getElementById('confirmBtn');

          openBtn.addEventListener('click', () => {
            modal.classList.add('open');
          });

          closeBtn.addEventListener('click', () => {
            modal.classList.remove('open');
          });

          confirmBtn.addEventListener('click', () => {
            modal.classList.remove('open');
          });
        </script>
      </body>
      </html>
    `);
  });

  test('should display modal as full-screen on mobile viewport when opened', async ({ page }) => {
    // Click the button to open the modal
    await page.getByRole('button', { name: 'Open Modal' }).click();

    // Get the modal element
    const modal = page.locator('#modal');

    // Verify modal is visible
    await expect(modal).toBeVisible();

    // Get the modal content
    const modalContent = page.locator('.modal-content');

    // Verify modal content takes full width on mobile
    const boundingBox = await modalContent.boundingBox();
    expect(boundingBox).not.toBeNull();

    if (boundingBox) {
      // On mobile (375px viewport), modal should be nearly full width
      expect(boundingBox.width).toBeGreaterThan(330);
      expect(boundingBox.width).toBeLessThanOrEqual(375);
    }
  });

  test('should close modal when close button is clicked on mobile', async ({ page }) => {
    // Open the modal
    await page.getByRole('button', { name: 'Open Modal' }).click();

    // Verify modal is visible
    const modal = page.locator('#modal');
    await expect(modal).toBeVisible();

    // Click close button
    await page.getByRole('button', { name: 'Close' }).click();

    // Verify modal is hidden
    await expect(modal).not.toBeVisible();
  });

  test('should close modal when confirm button is clicked on mobile', async ({ page }) => {
    // Open the modal
    await page.getByRole('button', { name: 'Open Modal' }).click();

    // Verify modal is visible
    const modal = page.locator('#modal');
    await expect(modal).toBeVisible();

    // Click confirm button
    await page.getByRole('button', { name: 'Confirm' }).click();

    // Verify modal is hidden
    await expect(modal).not.toBeVisible();
  });

  test('should display modal header and body content on mobile', async ({ page }) => {
    // Open the modal
    await page.getByRole('button', { name: 'Open Modal' }).click();

    // Verify modal header is visible
    const modalHeader = page.locator('.modal-header');
    await expect(modalHeader).toBeVisible();
    await expect(modalHeader).toContainText('Modal Title');

    // Verify modal body is visible
    const modalBody = page.locator('.modal-body');
    await expect(modalBody).toBeVisible();
    await expect(modalBody).toContainText('This is a modal dialog that should be full-screen on mobile devices');
  });

  test('should have proper modal footer buttons on mobile', async ({ page }) => {
    // Open the modal
    await page.getByRole('button', { name: 'Open Modal' }).click();

    // Verify footer buttons are visible
    const closeButton = page.getByRole('button', { name: 'Close' });
    const confirmButton = page.getByRole('button', { name: 'Confirm' });

    await expect(closeButton).toBeVisible();
    await expect(confirmButton).toBeVisible();

    // Verify buttons are clickable
    await expect(closeButton).toBeEnabled();
    await expect(confirmButton).toBeEnabled();
  });
});
